// Adapted from the user's SRS UI Figma reference: shared header, project tree, document outline.
let treeClosed=new Set(),creationPage=null,assistantMessages={},assistantOpen=true;
const routeNames={dashboard:'Home',projects:'Projects',requirements:'Requirements',planning:'Planning',architecture:'Architecture',meetings:'Live meetings',usage:'Usage',workspaces:'Workspaces',teams:'Teams',users:'User management',roles:'Roles',permissions:'Permissions',profile:'My profile',create:'Create'};
const assetIcon=n=>'<img class="asset-icon" alt="" src="assets/'+n+'-icon.png">';
function navLink(route,title,glyph=route){return '<a href="#'+route+'" class="nav-item '+(screen===route?'active':'')+'">'+icon(glyph)+'<span>'+title+'</span></a>'}
function treeToggle(key){if(treeClosed.has(key))treeClosed.delete(key);else treeClosed.add(key);captureReq();render()}
function treeProject(p){let open=!treeClosed.has('p'+p.id);return '<div class="tree-project"><button class="tree-row '+(selected===p.id&&['requirements','planning','architecture'].includes(screen)?'selected-project':'')+'" aria-expanded="'+open+'" onclick="treeToggle(\'p'+p.id+'\')"><span class="disclosure">'+(open?'⌄':'›')+'</span>'+icon('projects')+'<span>'+esc(p.name)+'</span></button>'+(open?'<div class="tree-documents">'+[['requirements','Requirements document'],['planning','Delivery plan'],['architecture','Architecture & tests']].map(([route,title])=>'<button class="'+(selected===p.id&&screen===route?'active':'')+'" onclick="selectDocument('+p.id+',\''+route+'\')">'+assetIcon('requirements')+'<span>'+title+'</span></button>').join('')+'</div>':'')+'</div>'}
function selectDocument(id,route){captureReq();selected=id;screen=route;filter='';history.replaceState(null,'','#'+route);if(window.matchMedia?.('(max-width:650px)').matches)document.body.classList.remove('nav-collapsed');render()}
openProject=function(id){selectDocument(id,'requirements')};
function projectTree(){return '<div class="tree-heading"><span>Teams & projects</span><button class="iconbtn" aria-label="Create team" onclick="openCreate(\'team\')">+</button></div>'+teams.filter(t=>t.space===workspace).map(t=>{const open=!treeClosed.has('t'+t.id);return '<div class="tree-team"><div class="team-line"><button class="tree-row" aria-expanded="'+open+'" onclick="treeToggle(\'t'+t.id+'\')"><span class="disclosure">'+(open?'⌄':'›')+'</span>'+icon('teams')+'<span>'+esc(t.name)+'</span></button><button class="tree-add" aria-label="Create project in '+esc(t.name)+'" onclick="openCreate(\'project\');setCreateTeam('+t.id+')">+</button></div>'+(open?projects.filter(p=>p.space===workspace&&p.team===t.id).map(treeProject).join(''):'')+'</div>'}).join('')+projects.filter(p=>p.space===workspace&&!teams.some(t=>t.id===p.team&&t.space===workspace)).map(treeProject).join('')+'<button class="new-tree-project" onclick="openCreate(\'project\')">+ New project</button>'}
function setCreateTeam(id){const s=document.querySelector('select[name="team"]');if(s)s.value=String(id)}
function toggleSidebar(){document.body.classList.toggle('nav-collapsed')}
function referenceHeader(){return '<header class="app-header"><div class="header-brand"><button class="iconbtn" onclick="toggleSidebar()" aria-label="Toggle sidebar">☰</button><a href="#dashboard" aria-label="Home"><img src="assets/devaide-logo.png" alt="DEVAIDE" width="85" height="32"></a></div><div class="header-workspace"><select aria-label="Choose workspace" onchange="switchWorkspace(Number(this.value))">'+spaces.map(w=>'<option value="'+w.id+'" '+(w.id===workspace?'selected':'')+'>'+esc(w.name)+'</option>').join('')+'<button class="iconbtn" aria-label="Create workspace" onclick="openCreate(\'workspace\')">+</button></div><div class="header-location">'+(['requirements','planning','architecture'].includes(screen)?esc(projects.find(p=>p.id===selected)?.name||'Project')+' <span> / </span> ':'')+esc(routeNames[screen]||'Workspace')+'</div><div class="header-profile"><span class="preview-pill">Prototype</span><a href="#profile">'+avatar(profile.name)+'<span>'+esc(profile.name)+'</span></a></div></header>'}
function referenceSidebar(){return '<aside class="reference-sidebar"><div class="nav-scroll">'+navLink('dashboard','Home','dashboard')+navLink('projects','All projects','projects')+navLink('meetings','Live meetings','teams')+projectTree()+'<div class="tree-heading management-heading">Workspace management</div>'+navLink('workspaces','Workspaces')+navLink('teams','Teams')+navLink('users','User management')+navLink('roles','Roles')+navLink('permissions','Permissions')+navLink('usage','Usage & activity','dashboard')+'</div><button class="sidebar-signout" onclick="navigate(\'login\')">'+icon('logout')+' Sign out</button></aside>'}
function creationScreen(){if(!creationPage)return heading('Create','Choose what you want to create.',button('New project',"openCreate('project')",true));return '<div class="creation-layout">'+heading(esc(creationPage.title),'Set up the details and choose the people who can collaborate.')+'<form onsubmit="'+creationPage.submit+'"><div class="creation-form">'+creationPage.body+'</div><div class="creation-actions"><button type="button" onclick="navigate(\''+creationPage.back+'\')">Cancel</button><button class="primary">'+(creationPage.title.startsWith('Manage')?'Save changes':'Create')+'</button></div></form></div>'}
const createWithMembers=openCreate;
openCreate=function(type){captureReq();const previous=modal;modal=function(title,body,submit){creationPage={title:title.replace(/^Create /,'Create new '),body,submit,back:({workspace:'workspaces',team:'teams',project:'projects',user:'users',role:'roles'})[type]||'dashboard'}};try{createWithMembers(type)}finally{modal=previous}navigate('create')};
const createItemBase=createItem;
createItem=function(e,type){const before=projects.length+users.length+roles.length+teams.length+spaces.length;createItemBase(e,type);if(before!==projects.length+users.length+roles.length+teams.length+spaces.length)navigate(({project:'projects',user:'users',role:'roles',team:'teams',workspace:'workspaces'})[type])};
const manageTeamBase=manageTeam;
manageTeam=function(id){captureReq();const previous=modal;modal=function(title,body,submit){creationPage={title,body,submit,back:'teams'}};try{manageTeamBase(id)}finally{modal=previous}navigate('create')};
const saveTeamBase=saveTeam;
saveTeam=function(e,id){saveTeamBase(e,id);navigate('teams')};
const phaseSections={requirements:[['capture','Project inputs'],['clarification','Clarification'],['specification','SRS document'],['quality','Quality review'],['baseline','Approval & baseline']],planning:[['backlog','Requirements & stories'],['capacity','Capacity & estimates'],['planning-review','Planning approval']],architecture:[['system-design','System architecture'],['traceability','Tests & traceability'],['architecture-review','Design approval']]};
function jumpSection(id){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function phaseOutline(route){const r=current(),p=plans[selected],a=architectures[selected];return '<div class="document-outline"><h3>Document structure</h3>'+['requirements','planning','architecture'].map((phase,i)=>{const done=[r?.approved,p?.approved,a?.approved][i];return '<div class="outline-group"><button class="outline-phase '+(phase===route?'active':'')+'" onclick="navigate(\''+phase+'\')"><span>'+String(i+1).padStart(2,'0')+' '+routeNames[phase]+'</span><small>'+ (done?'Approved':phase===route?'Editing':'')+'</small></button><div class="outline-progress"><i style="width:'+(done?100:phase===route?30:0)+'%"></i></div>'+ (phase===route?phaseSections[phase].map(([id,title],j)=>'<button class="outline-section" onclick="jumpSection(\''+id+'\')"><span>'+title+'</span><span class="outline-dot '+(done?'done':'')+'">'+(done?'✓':j+1)+'</span></button>').join(''):'')+'</div>'}).join('')+'<div class="outline-note">All sections are on this page. Select a heading to jump to it.</div></div>'}
function phaseAssistant(route){const messages=assistantMessages[selected+route]||[];return '<section class="document-assistant"><div class="assistant-heading"><span>✦</span><b>AI consultation</b><button class="iconbtn" aria-label="Hide assistant" onclick="assistantOpen=false;captureReq();render()">×</button></div><div class="assistant-context">Current phase <b>'+routeNames[route]+'</b><span class="badge gray">Preview · AI not connected</span></div><div class="assistant-scroll"><div class="assistant-message"><b>Let’s build a clear '+(route==='requirements'?'requirements baseline':route==='planning'?'delivery plan':'system design')+'.</b><p>'+({requirements:'Keep the scope specific, resolve open assumptions, and review measurable outcomes before approval.',planning:'Check every story against the SRS, estimate effort, and make dependencies explicit.',architecture:'Connect each requirement to a component and a test. Review security and failure paths.'})[route]+'</p></div>'+messages.map(m=>'<div class="assistant-message '+m.kind+'">'+esc(m.text)+'</div>').join('')+'<div class="suggestion-label">Suggested checks</div>'+({requirements:['Check open assumptions','Review approval criteria'],planning:['Review team capacity','Check backlog coverage'],architecture:['Review test coverage','Check security boundaries']})[route].map(t=>'<button class="assistant-suggestion" onclick="assistantPrompt(\''+t+'\')">'+t+' ↗</button>').join('')+'</div><form class="assistant-composer" onsubmit="submitAssistant(event)"><label for="assistantInput">Ask about this document</label><div><input id="assistantInput" name="message" placeholder="Write a question…" required><button class="primary" aria-label="Send preview question">↑</button></div></form></section>'}
function assistantPrompt(text){const k=selected+screen;const list=assistantMessages[k]??(assistantMessages[k]=[]);list.push({kind:'user-message',text});list.push({kind:'',text:'Preview guidance: '+(screen==='requirements'?'Review missing clarification answers and confirm the approver and notification target with stakeholders.':screen==='planning'?'Compare total estimated hours with available weekly team capacity. Confirm dependencies before approving.':'Verify that each requirement has a test, and review authorization, audit logging, and failure recovery.')+' A connected AI service is needed for analysis of your specific content.'});captureReq();render()}
function submitAssistant(e){e.preventDefault();const text=new FormData(e.target).get('message').trim();if(text)assistantPrompt(text)}
const phaseRenderers={requirements:requirementScreen,planning:planningScreen,architecture:architectureScreen};
function documentPage(route){if(!projectReady())return missingProject();const full=phaseRenderers[route](),start=full.indexOf('<section class="panel workflow-block"');const blocks=(route==='planning'&&!current().approved?'<div class="notice">Approve the requirements baseline before generating a plan.</div>':route==='architecture'&&!planState().approved?'<div class="notice">Approve the planning baseline before generating architecture.</div>':'')+full.slice(start);const p=projects.find(p=>p.id===selected),approved=route==='requirements'?current().approved:route==='planning'?planState().approved:architectureState().approved;return '<div class="document-workbench '+(!assistantOpen?'assistant-hidden':'')+'">'+phaseOutline(route)+'<div class="document-column"><div class="document-toolbar"><div><h1>'+routeNames[route]+' document</h1><span>'+esc(p.name)+'</span></div><div class="actions">'+badge(approved?'Approved':'Draft')+button('Save','savePhaseDraft()')+(route==='requirements'?button('↓ Export','exportSrs()',true):route==='architecture'&&approved?button('↓ Export','exportHandoff()',true):'')+(!assistantOpen?button('✦ Assistant','assistantOpen=true;captureReq();render()'):'')+'</div></div><div class="document-scroll"><div class="document-version"><span>Working version · '+(approved?'Baseline locked':'Editable draft')+'</span><span>Session only</span></div>'+blocks+'</div></div>'+(assistantOpen?phaseAssistant(route):'')+'</div>'}
function savePhaseDraft(){captureReq();toast('Draft saved for this session.')}
function recentProjectRows(){const ps=workspaceProjects();return ps.length?ps.map(p=>'<button class="recent-document" onclick="openProject('+p.id+')">'+assetIcon('requirements')+'<span><b>'+esc(p.name)+'</b><small>'+esc(teams.find(t=>t.id===p.team)?.name||'Unassigned')+' / Requirements document</small></span>'+badge(reqs[p.id]?.approved?'Approved':p.status)+'<span class="recent-arrow">→</span></button>').join(''):'<div class="empty">No matching projects. Create a project to begin.</div>'}
dashboard=function(){const ps=projects.filter(p=>p.space===workspace);return heading('Home','Continue your work or start a new project.')+'<section class="home-quick"><h2>Quick actions</h2><div class="quick-grid"><button onclick="openCreate(\'project\')">'+assetIcon('requirements')+'<span><b>Create requirements document</b><small>Start a project and define what needs to be built.</small></span><span>+</span></button><button onclick="navigate(\'meetings\')">'+assetIcon('interview')+'<span><b>Open meeting workspace</b><small>Review meeting context, transcripts, and translations.</small></span><span>↗</span></button></div></section><div class="reference-metrics">'+[['Projects',ps.length],['Requirements approved',ps.filter(p=>reqs[p.id]?.approved||p.status==='Approved').length],['Planning approved',ps.filter(p=>plans[p.id]?.approved).length],['Architecture approved',ps.filter(p=>architectures[p.id]?.approved).length]].map(([label,n])=>'<div><span>'+label+'</span><strong>'+n+'</strong></div>').join('')+'</div><div class="recent-heading"><h2>Project documents</h2><label class="document-search">'+icon('search')+'<input aria-label="Search project documents" placeholder="Search projects…" oninput="filter=this.value;document.getElementById(\'recentProjects\').innerHTML=recentProjectRows()"></label></div><section class="panel recent-list" id="recentProjects">'+recentProjectRows()+'</section><div class="dashboard-charts">'+panel('Workspace activity',workspace===0?lineChart():'<div class="empty">No activity history yet.</div>','<span class="badge gray">Sample history</span>')+panel('Approved baselines',bars([ps.filter(p=>reqs[p.id]?.approved||p.status==='Approved').length,ps.filter(p=>plans[p.id]?.approved).length,ps.filter(p=>architectures[p.id]?.approved).length],['Requirements','Planning','Architecture']))+'</div>'};
authScreen=function(register=false){return '<div class="reference-auth"><a href="#dashboard" class="auth-logo"><img src="assets/devaide-logo.png" alt="DEVAIDE" width="85" height="32"></a><div class="auth-box"><h1>'+(register?'Create your account':'Welcome back')+'</h1><p class="sub">Your product development workspace.</p><form onsubmit="authSubmit(event,'+register+')">'+(register?field('Full name','name'):'')+field('Email address','email','','email')+'<label class="field">Password<input type="password" name="password" minlength="8" required autocomplete="'+(register?'new-password':'current-password')+'"></label><button class="primary">'+(register?'Create demo account':'Sign in to demo')+'</button></form><p>'+(register?'Already have an account? <a href="#login">Sign in</a>':'New here? <a href="#register">Create an account</a>')+'</p><div class="auth-note">UI prototype. Use sample credentials. Authentication is not connected and passwords are not saved.</div></div></div>'};
render=function(){if(['login','register'].includes(screen)){$('#root').innerHTML=authScreen(screen==='register');return}if(['requirements','planning','architecture','meetings'].includes(screen))projectReady();const isDocument=['requirements','planning','architecture'].includes(screen)&&!!selected;const screens={dashboard,projects:listProjects,meetings:meetingScreen,usage:usageScreen,workspaces:workspaceScreen,teams:teamScreen,users:userScreen,roles:roleScreen,permissions:permissionsScreen,profile:profileScreen,create:creationScreen,requirements:()=>documentPage('requirements'),planning:()=>documentPage('planning'),architecture:()=>documentPage('architecture')};$('#root').innerHTML=referenceHeader()+referenceSidebar()+'<div class="reference-layout '+(isDocument?'document-layout':'')+'"><main>'+(screens[screen]||dashboard)()+'</main>'+(!isDocument?'<footer>AI Product Development Assistant <span>Interactive prototype · Session only</span></footer>':'')+'</div>';if(screen==='meetings')updateTranscript()};
render();

window.addEventListener('hashchange',()=>{if(window.matchMedia?.('(max-width:650px)').matches)document.body.classList.remove('nav-collapsed')});
